-- Cardoso Marketing Hub — plano de mídias 14/10/2026 a 05/01/2027 (versão com briefing de arte).
--
-- Fonte: Plano_Midias_Cardoso_Playmi_Topi_14out26-05jan27.xlsx (abas Peças, Briefing de arte, Guia das
-- marcas, Produção, Marcos, Estratégia e Pendências). 112 assuntos · 405 destinos · 23 marcos.
--
-- Substitui QUALQUER plano que estiver no Hub (o antigo de Ago/26–Mar/27 e a importação da 0114, se ela
-- rodou). Antes de apagar, cópia completa em backup_plano_20261013_* (RLS sem policy: só o SQL Editor lê).
--
-- Novidades de estrutura:
--   · social_topics.brief (jsonb): o briefing de arte de cada assunto (formato e medida, material base, meta,
--     como medir, por que agora, estratégia usada, público, mensagem-chave, gancho, estrutura, texto na arte,
--     direção visual, obrigatório/evitar, artes derivadas e prazos para a Fabiana)
--   · social_strategy_notes: estratégia do período, pendências, guia das marcas e formatos/medidas
--
-- Roda depois de 0113 (pode pular a 0114). Idempotente: backup e limpeza só na primeira vez.

set lock_timeout = '10s';

begin;

alter table public.social_topics add column if not exists brief jsonb not null default '{}'::jsonb;

create table if not exists public.social_strategy_notes (
  ext_key text primary key,
  section text not null check (section in ('estrategia', 'pendencia', 'guia', 'formato', 'leitura')),
  brand text,
  item text not null default '',
  value text not null default '',
  note text,
  ord int not null default 0,
  done boolean not null default false,       -- pendência resolvida
  updated_by uuid references public.profiles (id),
  updated_at timestamptz not null default now()
);
alter table public.social_strategy_notes enable row level security;
drop policy if exists "ssn_select" on public.social_strategy_notes;
create policy "ssn_select" on public.social_strategy_notes for select to authenticated using (true);
drop policy if exists "ssn_write" on public.social_strategy_notes;
create policy "ssn_write" on public.social_strategy_notes for all to authenticated
  using (public.can_release_content()) with check (public.can_release_content());

-- 1) backup (cópia de tudo o que ainda não está no backup)
create table if not exists public.backup_plano_20261013_items as table public.social_plan_items with no data;
create table if not exists public.backup_plano_20261013_topics as table public.social_topics with no data;
create table if not exists public.backup_plano_20261013_comments as table public.social_plan_comments with no data;
create table if not exists public.backup_plano_20261013_deadlines as table public.social_plan_deadlines with no data;
alter table public.backup_plano_20261013_topics add column if not exists brief jsonb;
alter table public.backup_plano_20261013_items enable row level security;
alter table public.backup_plano_20261013_topics enable row level security;
alter table public.backup_plano_20261013_comments enable row level security;
alter table public.backup_plano_20261013_deadlines enable row level security;

do $$
begin
  if exists (select 1 from public.social_topics where ext_key like 'plano-2026-10b:%') then
    raise notice 'Esta versão do plano já está no banco: backup e limpeza pulados.';
    return;
  end if;
  insert into public.backup_plano_20261013_items
    select * from public.social_plan_items i where not exists (select 1 from public.backup_plano_20261013_items b where b.id = i.id);
  insert into public.backup_plano_20261013_topics
    select * from public.social_topics t where not exists (select 1 from public.backup_plano_20261013_topics b where b.id = t.id);
  insert into public.backup_plano_20261013_comments
    select * from public.social_plan_comments c where not exists (select 1 from public.backup_plano_20261013_comments b where b.id = c.id);
  insert into public.backup_plano_20261013_deadlines
    select * from public.social_plan_deadlines d where not exists (select 1 from public.backup_plano_20261013_deadlines b where b.id = d.id);

  -- 2) apaga o plano que estava no Hub
  delete from public.comment_reactions where source = 'social_plan';
  update public.social_plan_items set merged_into = null where merged_into is not null;
  delete from public.social_plan_items;
  delete from public.social_topics;
  delete from public.social_plan_deadlines;
end $$;

