insert into public.social_topics (ext_key, title, brand, sku, front, objective, strategy, cta, media_use, licensed, brief)
select ext_key, title, brand, coalesce(sku, ''), coalesce(front, ''), coalesce(objective, ''), coalesce(strategy, ''), coalesce(cta, ''), coalesce(media_use, ''), licensed, brief::jsonb
  from _t
on conflict (ext_key) do update set brief = excluded.brief;

update public.social_topics t
   set product_id = p.id, product = p.name
  from public.products p
 where t.ext_key like 'plano-2026-10b:%' and t.product_id is null
   and t.sku ~ '^[0-9]+$' and ltrim(p.code, '0') = ltrim(t.sku, '0');

-- 4) destinos (matriz primeiro)
create temp table _i (ext_id text, topic_key text, canal text, link_kind text, pub_date date, pub_time time, weekday text, month_label text,
  piece_type text, format text, origin text, caption text, creative_url text, creative_changed boolean, mirror_facebook boolean) on commit drop;
