on conflict (ext_key) do nothing;

-- 6) estratégia, pendências, guia das marcas e formatos
insert into public.social_strategy_notes (ext_key, section, brand, item, value, note, ord)
select ext_key, section, brand, coalesce(item, ''), coalesce(value, ''), note, ord from (values
  ('plano-2026-10b:e00','estrategia',null,'Período','14/10/2026 a 05/01/2027. Playmi: fila pronta de outubro (14 a 31/10) e plano novo a partir de 01/11. Tópi e Cardoso: plano novo desde 14/10.',null,0),
  ('plano-2026-10b:e01','estrategia',null,'Objetivo Cardoso','Gerar demanda de novos revendedores, com foco em quem tem e-commerce. Toda quinta tem uma peça de revenda com mídia paga e CTA para o WhatsApp Comercial.',null,1),
  ('plano-2026-10b:e02','estrategia',null,'Objetivo Playmi','Desejo para a mãe B–C e giro no varejo parceiro (onde comprar).',null,2),
  ('plano-2026-10b:e03','estrategia',null,'Objetivo Tópi','Giro e impulso no bazar, público C–D; dar vitrine à curva A que não tinha conteúdo.',null,3),
  ('plano-2026-10b:e04','estrategia',null,'Pilares Cardoso','1) Por que revender Cardoso (fábrica, o que gira, mix, licenças, atendimento) · 2) Campanha do mês para o lojista (Natal Musical, Licenciados, verão, Páscoa, ABRIN) · 3) Relacionamento (datas).',null,4),
  ('plano-2026-10b:e05','estrategia',null,'Pilares Playmi','1) Brincar de verdade · 2) Personagens (Spidey e Princesas até 31/03; Bluey lançamento; Smurfs, Luna, Galinha com frequência baixa) · 3) Presente certo (guias por idade).',null,5),
  ('plano-2026-10b:e06','estrategia',null,'Pilares Tópi','1) Achadinho que rende brincadeira (vídeo pronto) · 2) Curva A sem conteúdo (imagem gerada) · 3) Ideia de brincadeira (carrossel salvável).',null,6),
  ('plano-2026-10b:e07','estrategia',null,'Cadência','Playmi: Ter e Qui Reels 12h, Sáb carrossel 20h30. Tópi: Qua e Sex Reels 12h, Sáb carrossel 20h30. Cardoso: Seg Instagram 11h, Ter LinkedIn 08h30, Qui Instagram 11h (revenda). 1 Stories novo por marca por semana; os outros Stories reaproveitam o feed.',null,7),
  ('plano-2026-10b:e08','estrategia',null,'Reaproveitamento','Facebook espelha o Instagram (sem linha própria). Reels Tópi → TikTok D+1. Reels Playmi/Tópi → playlists do YouTube (Shorts). Status do WhatsApp reaproveita Reels. LinkedIn → Google Meu Negócio (adapta). Imagens → Pinterest a partir de novembro (adapta, 2 pins por semana).',null,8),
  ('plano-2026-10b:e09','estrategia',null,'Cardoso Black','Ação interna: só Canal Representantes e Canais Clientes. Nenhuma peça nas redes.',null,9),
  ('plano-2026-10b:e10','estrategia',null,'WhatsApp','Canal de aviso de campanha. Como a nova área comercial ainda não está ativa, o material (arte, vídeo, lâmina) vai anexo na própria mensagem. Clientes por região: mesmo texto, exceto quando a condição muda (ex.: frete SP/RJ no Sudeste).',null,10),
  ('plano-2026-10b:e11','estrategia',null,'Área comercial','Fora deste bloco: nenhum assunto ou legenda fala da nova área comercial até ela ser liberada (previsão dez/jan). Quando for lançada, entra como frente própria.',null,11),
  ('plano-2026-10b:e12','estrategia',null,'Mídia paga','R$ 1.500/mês sem divisão por marca. ''Mídia paga liberada'' marca as peças elegíveis: revenda Cardoso (sempre) e Reels Playmi/Tópi não licenciados no pico de Natal. Licenciado só com aval do licenciador para anúncio.',null,12),
  ('plano-2026-10b:e13','estrategia',null,'Aprovação','Regra padrão: pauta + legenda D-20 (D-25 com licenciado), criativo D-8 (D-11 com licenciado). Até o início de novembro os prazos já passaram: aprovação comprimida (aba Produção). A partir de dezembro: pauta do mês inteiro até o dia 5 do mês anterior.',null,13),
  ('plano-2026-10b:e14','estrategia',null,'Pocoyo','Fora do conteúdo de consumidor. Entra só nos avisos B2B de licenciados (queima).',null,14),
  ('plano-2026-10b:p00','pendencia',null,'1','Fabiana: aprovar em bloco, de forma comprimida, as peças de 14/10 a ~07/11 (Tópi e Cardoso) — o prazo padrão de 20 dias já passou.',null,0),
  ('plano-2026-10b:p01','pendencia',null,'2','Licenciadores: enviar em lote as peças com personagem (ver coluna ''Licenciado'' na aba Produção). Spidey de outubro ficou como orgânico até o aval cobrir anúncio.',null,1),
  ('plano-2026-10b:p02','pendencia',null,'3','Comercial: confirmar o corte de faturamento da Black, já que 20/11 é feriado nacional.',null,2),
  ('plano-2026-10b:p03','pendencia',null,'4','Moltó: confirmar se Totokross, Carrinho de Puxar, Estação de Resgate, Moto Speed e Dino Jurássico (linha Play&Molto) precisam de aprovação antes de publicar.',null,3),
  ('plano-2026-10b:p04','pendencia',null,'5','Marca dos produtos: Boliche (7001), Dino Sabidinho (1007), Leva Papinha (0124), Teltaluga/Tortuga, Invictus Sky, Mesinha 3054 e Robô-Blocks estão como Tópi no Drive e como Playmi no produtos_catalogo_2026.csv do Hub. O plano segue o Drive.',null,4),
  ('plano-2026-10b:p05','pendencia',null,'6','Link do criativo: a pasta do 8028 (Carrinho de Puxar Rosa) não foi encontrada. Peças marcadas ''Gerar'' têm a pasta do produto como destino do material.',null,5),
  ('plano-2026-10b:p06','pendencia',null,'7','Formatos de outubro da Playmi considerados Reels; ajustar se algum for carrossel.',null,6),
  ('plano-2026-10b:p07','pendencia',null,'8','Avisos de WhatsApp: anexar na mensagem a arte/vídeo/lâmina citados (a área comercial ainda não está ativa).',null,7),
  ('plano-2026-10b:p08','pendencia',null,'9','WhatsApp Status: o Hub tem um canal só; Status do número Comercial (peças Cardoso) e do SAC (peças Playmi/Tópi) ficam na mesma linha de canal.',null,8),
  ('plano-2026-10b:p09','pendencia',null,'10','Lançamentos 2027: entram no plano quando o desenvolvimento passar as informações.',null,9),
  ('plano-2026-10b:g010','guia','Playmi','Público','Mãe B–C (decide a compra) e quem presenteia (pais, avós, tios). Usuário: criança de 12 meses a 6 anos.',null,1),
  ('plano-2026-10b:g011','guia','Tópi','Público','Famílias C–D, compra por impulso em Lojas Bazar. Usuário: criança de 1 a 10 anos.',null,1),
  ('plano-2026-10b:g012','guia','Cardoso','Público','Revendedores: donos de loja e de e-commerce de brinquedos e presentes (novos clientes) e a carteira atual via representantes.',null,1),
  ('plano-2026-10b:g020','guia','Playmi','Tom de voz','Claro, casual e afetivo. Fala ao lado da família, celebra cada descoberta, nunca impõe regras nem usa termos técnicos.',null,2),
  ('plano-2026-10b:g021','guia','Tópi','Tom de voz','Leve, casual, próximo, simples e inclusivo. Nada de formalismo ou palavra difícil; nunca impositivo.',null,2),
  ('plano-2026-10b:g022','guia','Cardoso','Tom de voz','Direto, confiável e de indústria: fala de giro, fábrica, mix e atendimento. Sem exagero e sem promessa que o comercial não cumpre.',null,2),
  ('plano-2026-10b:g030','guia','Playmi','Tipografia','Títulos: Goldray · Textos: Urbanist',null,3),
  ('plano-2026-10b:g031','guia','Tópi','Tipografia','Títulos: Chill Kids · Textos: Maven Pro',null,3),
  ('plano-2026-10b:g032','guia','Cardoso','Tipografia','Títulos: Redonda · Textos: Figtree',null,3),
  ('plano-2026-10b:g040','guia','Playmi','Paleta','Azul #005CA9 · Ciano #00B2C7 · Amarelo #FFE500 · Laranja #E87821 (base); cores das linhas conforme o guia',null,4),
  ('plano-2026-10b:g041','guia','Tópi','Paleta','Laranja #EA5C18 · Amarelo #F3D22A · Azul #2EBADA',null,4),
  ('plano-2026-10b:g042','guia','Cardoso','Paleta','Azul-marinho #0A2530 · Vermelho #DA3A2F · Turquesa #4CBDC7 · Off-white #F9F8F8 · Vinho #6A151F',null,4),
  ('plano-2026-10b:g050','guia','Playmi','Assinatura','Tagline: Brincar é crescer, juntos! · Slogans: O primeiro passo é brincar · Descobrir, criar e crescer juntos.',null,5),
  ('plano-2026-10b:g051','guia','Tópi','Assinatura','Tagline: Brincar é Tópi! · Slogan: Se divertir é Tópi.',null,5),
  ('plano-2026-10b:g052','guia','Cardoso','Assinatura','Construímos muito mais que brinquedos. Construímos confiança.',null,5),
  ('plano-2026-10b:g060','guia','Playmi','Tom fotográfico','Criança brincando de verdade, luz natural, ambiente de casa, afeto e família. Produto sempre identificável.',null,6),
  ('plano-2026-10b:g061','guia','Tópi','Tom fotográfico','Produto em movimento, cores fortes, fundo simples e alegre; cenas do dia a dia de famílias brasileiras.',null,6),
  ('plano-2026-10b:g062','guia','Cardoso','Tom fotográfico','Fábrica real, produto em escala, caixas, representante e lojista. Produto Playmi/Tópi aparece como portfólio.',null,6),
  ('plano-2026-10b:g070','guia','Playmi','Regras de toda arte','Logo Playmi no fim do vídeo ou no último card. Idade do produto sempre visível. Sem preço. Licenciado: só arte com aval do licenciador e logo da licença conforme o manual dele.',null,7),
  ('plano-2026-10b:g071','guia','Tópi','Regras de toda arte','Vídeo curto e direto (até 15 s). Logo Tópi no fim. Sem preço na arte. Texto na tela grande e curto.',null,7),
  ('plano-2026-10b:g072','guia','Cardoso','Regras de toda arte','Sem preço, desconto ou condição comercial nas redes. Cardoso Black só no WhatsApp. Não citar a nova área comercial (ainda não está ativa). CTA de revenda sempre para o WhatsApp Comercial.',null,7),
  ('plano-2026-10b:f08','formato',null,'Reels / Shorts / TikTok','1080 × 1920 (9:16)','12 a 20 s; texto dentro da área segura (sem os 250 px de cima e de baixo); legenda na tela',8),
  ('plano-2026-10b:f09','formato',null,'Carrossel Instagram','1080 × 1350 (4:5)','5 a 7 cards; capa com título curto; último card com CTA e logo',9),
  ('plano-2026-10b:f10','formato',null,'Stories','1080 × 1920 (9:16)','1 tela; sticker (enquete, caixinha ou link) no centro',10),
  ('plano-2026-10b:f11','formato',null,'Post LinkedIn','1080 × 1350 (4:5)','Arte estática, título de até 8 palavras; o texto longo vai na legenda',11),
  ('plano-2026-10b:f12','formato',null,'Pin (Pinterest)','1000 × 1500 (2:3)','Foto do produto com título curto; link para a página do produto',12),
  ('plano-2026-10b:f13','formato',null,'Aviso WhatsApp','1080 × 1080 (1:1)','Arte com título da campanha e data; vídeo ou lâmina anexos quando citados no texto',13),
  ('plano-2026-10b:f14','formato',null,'Google Meu Negócio','1200 × 900 (4:3)','Foto ou arte simples com logo Cardoso',14),
  ('plano-2026-10b:l15','leitura',null,null,'1 linha por assunto (a peça principal). As colunas ''o que queremos atingir'', ''por que este post agora'' e ''estratégia usada'' explicam a decisão; as colunas de gancho, estrutura e texto na arte dizem o que executar.',null,15),
  ('plano-2026-10b:l16','leitura',null,null,'''Artes derivadas'' lista o que precisa ser criado além da peça principal (Stories novo, pin, aviso de WhatsApp) e onde o mesmo arquivo é só reaproveitado.',null,16),
  ('plano-2026-10b:l17','leitura',null,null,'Prazos: pauta + legenda vão para a Fabiana antes; o criativo vai depois. ''Comprimido'' = o prazo padrão já passou e precisa de aprovação em bloco.',null,17),
  ('plano-2026-10b:l18','leitura',null,null,'Fontes dos dados: painel comercial jul/25–jul/26 (giro, clientes), diretriz comercial 26/27 (campanhas, estoque parado, licenciados), inventário do Drive (material pronto) e guias de marca.',null,18)
) v (ext_key, section, brand, item, value, note, ord)
