-- 7) conferência
do $$
declare nt int; ni int; nm int; sem_matriz int; sem_brief int;
begin
  select count(*) into nt from public.social_topics where ext_key like 'plano-2026-10b:%';
  select count(*) into ni from public.social_plan_items where ext_id like 'plano-2026-10b:%';
  select count(*) into nm from public.social_plan_deadlines where ext_key like 'plano-2026-10b:%';
  select count(*) into sem_brief from public.social_topics where ext_key like 'plano-2026-10b:%' and brief = '{}'::jsonb;
  select count(*) into sem_matriz from public.social_topics t where t.ext_key like 'plano-2026-10b:%'
     and (select count(*) from public.social_plan_items i where i.topic_id = t.id and i.link_kind = 'matriz') <> 1;
  if nt <> 112 or ni <> 405 or nm <> 23 or sem_matriz > 0 then
    raise exception 'ABORTADO: entraram % assuntos, % destinos e % marcos (esperado 112, 405 e 23); % sem 1 matriz', nt, ni, nm, sem_matriz;
  end if;
  raise notice 'Plano no ar: % assuntos, % destinos, % marcos; % assunto(s) sem briefing.', nt, ni, nm, sem_brief;
end $$;

commit;

notify pgrst, 'reload schema';

